import{_ as c}from"./chunks/5.DE4pC5lW.js";import{_ as r,I as o,m as d,p,ac as a,E as i,q as s,N as n}from"./chunks/framework.B20rRf_H.js";const _=JSON.parse('{"title":"Assign Unique Scores","description":"Learn how to give every entity its own unique ID score so that commands can tell identical targets apart","frontmatter":{"title":"Assign Unique Scores","category":"Scoreboard Systems","tags":["intermediate"],"license":true,"mentions":["katsutosakae","akiponggg0119"],"description":"Learn how to give every entity its own unique ID score so that commands can tell identical targets apart"},"headers":[{"level":2,"title":"Introduction","slug":"introduction","link":"#introduction","children":[]},{"level":2,"title":"Setup","slug":"setup","link":"#setup","children":[]},{"level":2,"title":"System","slug":"system","link":"#system","children":[]},{"level":2,"title":"Explanation","slug":"explanation","link":"#explanation","children":[]},{"level":2,"title":"Using the ID","slug":"using-the-id","link":"#using-the-id","children":[]},{"level":2,"title":"Performance","slug":"performance","link":"#performance","children":[]},{"level":2,"title":"Tick JSON","slug":"tick-json","link":"#tick-json","children":[]}],"relativePath":"commands/assign-unique-score.md","filePath":"commands/assign-unique-score.md"}'),h={name:"commands/assign-unique-score.md"};function u(m,e,k,g,y,b){const t=o("CodeHeader"),l=o("FolderView");return d(),p("div",null,[e[0]||(e[0]=a('<h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Commands often need to tell two identical entities apart. A tag cannot do this, because a tag is only on or off. It holds no value, so every tagged entity looks the same.</p><p>A <strong>unique ID</strong> solves this. It is a score that only one entity has. That number can then be copied onto the entities it spawns, so a parent and all of its children carry the same value. <a href="/commands/comparing-scores">Comparing those scores</a> tells you which entities belong to which parent, and which belong to someone else. This is what makes an entity based system work in multiplayer, where the same commands run for every player at once.</p><p>The system below hands out these IDs in one tick, however many entities appear at once, and is safe to run forever.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p><em>Type the following command in Chat:</em></p><p><code class="shiki"><span>/scoreboard objectives add wiki:unique_id dummy</span></code></p><p>If you are working with functions and prefer to have the objective added automatically on world initialization, follow the process outlined in <a href="/commands/on-first-world-load">On First World Load</a>.</p><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2>',9)),i(t,{path:"BP/functions/wiki/scoreboard/entities/assign_unique_id.mcfunction"}),e[1]||(e[1]=a(`<div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes dark-plus light-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#6A9955;--shiki-light:#008000;">## Start Tracking Every Entity (Existing Scores Are Kept)</span></span>
<span class="line"><span style="--shiki-dark:#CE9178;--shiki-light:#0000FF;">scoreboard players add @e wiki:unique_id 0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-dark:#6A9955;--shiki-light:#008000;">## Remember the Highest ID Handed Out So Far</span></span>
<span class="line"><span style="--shiki-dark:#CE9178;--shiki-light:#0000FF;">scoreboard players operation .Max wiki:unique_id &gt; * wiki:unique_id</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-dark:#6A9955;--shiki-light:#008000;">## Number the Untagged Entities From 1 to n</span></span>
<span class="line"><span style="--shiki-dark:#CE9178;--shiki-light:#0000FF;">execute as @e[tag=!wiki:set_unique_id,scores={wiki:unique_id=0}] at @e[tag=!wiki:set_unique_id,scores={wiki:unique_id=0}] run scoreboard players add @s wiki:unique_id 1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-dark:#6A9955;--shiki-light:#008000;">## Offset Them Past Every ID That Already Exists</span></span>
<span class="line"><span style="--shiki-dark:#CE9178;--shiki-light:#0000FF;">scoreboard players operation @e[tag=!wiki:set_unique_id,scores={wiki:unique_id=0..}] wiki:unique_id += .Max wiki:unique_id</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-dark:#6A9955;--shiki-light:#008000;">## Mark Them as Done</span></span>
<span class="line"><span style="--shiki-dark:#CE9178;--shiki-light:#0000FF;">tag @e[tag=!wiki:set_unique_id,scores={wiki:unique_id=0..}] add wiki:set_unique_id</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p><img src="`+c+`" alt="Chain of 5 Command Blocks"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The order matters. <code class="shiki"><span>.Max</span></code> must be read before any new ID is written, or the temporary values from command 3 would count as existing IDs.</p></div><h2 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to &quot;Explanation&quot;">​</a></h2><p><strong>Command 1:</strong> Adding <code class="shiki"><span>0</span></code> starts tracking every entity and leaves existing scores alone. An entity that has never been seen starts at <code class="shiki"><span>0</span></code>, and that <code class="shiki"><span>0</span></code> is what marks it as new.</p><p><strong>Command 2:</strong> The <code class="shiki"><span>&gt;</span></code> operation keeps the larger of the two values, so running it against the wildcard (<code class="shiki"><span>*</span></code>) leaves <code class="shiki"><span>.Max</span></code> holding the highest score in the objective. <code class="shiki"><span>.Max</span></code> is compared with itself too, so it never goes down. An ID from a dead entity is never given out again.</p><div class="info custom-block"><p class="custom-block-title">NOTE:</p><p>Wildcard (<code class="shiki"><span>*</span></code>) compares with all tracked scores, which includes offline players. That is what we want here, so a returning player cannot clash with an ID given out while they were away.</p></div><p><strong>Command 3:</strong> This uses <a href="/commands/execution-forking">Execution Forking</a>. The <code class="shiki"><span>as</span></code> subcommand splits the command into one run per new entity. The <code class="shiki"><span>at</span></code> subcommand splits it again, but its selector is checked separately for each run, after the previous run has already written its score. Each run therefore matches fewer entities than the last, and everyone ends up with a different number.</p><p>To illustrate, with three new entities A, B and C:</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:center;">Instance (<code class="shiki"><span>as</span></code>)</th><th style="text-align:center;">Entities still at <code class="shiki"><span>0</span></code> when <code class="shiki"><span>at</span></code> resolves</th><th style="text-align:center;">Times the <code class="shiki"><span>add</span></code> runs</th><th style="text-align:center;">Resulting score</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">A</td><td style="text-align:center;">A, B, C</td><td style="text-align:center;">3</td><td style="text-align:center;"><code class="shiki"><span>A = 3</span></code></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">B</td><td style="text-align:center;">B, C</td><td style="text-align:center;">2</td><td style="text-align:center;"><code class="shiki"><span>B = 2</span></code></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">C</td><td style="text-align:center;">C</td><td style="text-align:center;">1</td><td style="text-align:center;"><code class="shiki"><span>C = 1</span></code></td></tr></tbody></table><p><em>Once A has a score it no longer matches <code class="shiki"><span>scores={wiki:unique_id=0}</span></code>, which is why the second run only splits twice.</em></p><p><strong>Command 4:</strong> Command 3 always starts counting from <code class="shiki"><span>1</span></code>, so those numbers would clash with entities that already exist. Adding <code class="shiki"><span>.Max</span></code> moves the whole batch above every ID in use. In the example above, with <code class="shiki"><span>.Max</span></code> at <code class="shiki"><span>12</span></code>, A, B and C become <code class="shiki"><span>15</span></code>, <code class="shiki"><span>14</span></code> and <code class="shiki"><span>13</span></code>.</p><p><strong>Command 5:</strong> The tag keeps these entities out of commands 3 and 4 from now on, so an ID is given once and never changes.</p><h2 id="using-the-id" tabindex="-1">Using the ID <a class="header-anchor" href="#using-the-id" aria-label="Permalink to &quot;Using the ID&quot;">​</a></h2><p>The ID can be copied into a second objective to link two entities together. In this example, each player claims the armor stand nearest to them.</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes dark-plus light-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#6A9955;--shiki-light:#008000;">## Copy Your Own ID Into Another Objective to Store a Reference</span></span>
<span class="line"><span style="--shiki-dark:#CE9178;--shiki-light:#0000FF;">execute as @a[tag=wiki:set_unique_id] at @s run scoreboard players operation @e[type=armor_stand,c=1] wiki:target_id = @s wiki:unique_id</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-dark:#6A9955;--shiki-light:#008000;">## Compare the Scores</span></span>
<span class="line"><span style="--shiki-dark:#CE9178;--shiki-light:#0000FF;">execute as @e[tag=wiki:set_unique_id] at @e[type=armor_stand,scores={wiki:target_id=1..}] if score @s wiki:unique_id = @e[type=armor_stand,scores={wiki:target_id=1..},c=1] wiki:target_id run say @e[type=armor_stand,scores={wiki:target_id=1..},c=1] is connected to @s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>Command 1:</strong> Every tagged player copies their own ID onto the closest armor stand, into a second objective called <code class="shiki"><span>wiki:target_id</span></code>. The stand now stores who owns it.</p><p><strong>Command 2:</strong> For each claimed stand, this looks for the entity whose <code class="shiki"><span>wiki:unique_id</span></code> matches the stand&#39;s <code class="shiki"><span>wiki:target_id</span></code>. That finds the owner again, without the two needing to be near each other.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code class="shiki"><span>c=1</span></code> picks the closest stand, so two players next to the same armor stand will both claim it and the second one wins. Add a check of your own if a target may only be claimed once.</p></div><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><p>Command 3 runs n² times for n new entities, because each of the n runs from <code class="shiki"><span>as</span></code> splits again at <code class="shiki"><span>at</span></code>. A few entities per tick is fine, but a mob farm or a <code class="shiki"><span>/summon</span></code> loop that spawns dozens at once can reach thousands of runs in a single tick.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you only need IDs for one kind of target, add <code class="shiki"><span>type=</span></code> to both selectors. Limiting the system to <code class="shiki"><span>@e[type=player]</span></code> or to your own custom entity keeps the cost low whatever else is happening on the world.</p></div><blockquote><p>Note: <code class="shiki"><span>@e</span></code> does not match entities in unloaded chunks. This is fine, as a tagged entity keeps its score and tag while unloaded, and a new one gets its ID on the first tick after its chunk loads.</p></blockquote><h2 id="tick-json" tabindex="-1">Tick JSON <a class="header-anchor" href="#tick-json" aria-label="Permalink to &quot;Tick JSON&quot;">​</a></h2><p>If you are using functions instead of command blocks, the <code class="shiki"><span>assign_unique_id</span></code> function must be added to the <code class="shiki"><span>tick.json</span></code> in order to loop and run it continuously. Multiple files can be added to the <code class="shiki"><span>tick.json</span></code> by placing a comma after each string. Refer to <a href="/commands/mcfunctions#tick-json">Functions</a> documentation for further info.</p>`,25)),i(t,{path:"BP/functions/tick.json"}),e[2]||(e[2]=a(`<div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">    &quot;values&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: [</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;wiki/scoreboard/entities/assign_unique_id&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">]</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>If using functions, your pack folder structure will be as follows:</p>`,2)),i(l,{paths:["BP/functions/wiki/scoreboard/entities/assign_unique_id.mcfunction","BP/functions/wiki/main.mcfunction","BP/functions/tick.json","BP/manifest.json","BP/pack_icon.png"]}),e[3]||(e[3]=s("p",null,[n("In this setup, the "),s("code",{class:"shiki"},[s("span",null,"assign_unique_id")]),n(" function is called by "),s("code",{class:"shiki"},[s("span",null,"main.mcfunction")]),n(", which is executed every tick via "),s("code",{class:"shiki"},[s("span",null,"tick.json")]),n(".")],-1))])}const v=r(h,[["render",u]]);export{_ as __pageData,v as default};
